selected.compute:
pool = read('/input/options')
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    selection = result
if not exists('/output/selection'):
    write('/output/selection', selection)
if status('report') != 'sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
